      var bw = clamp(value / max, 0, 1) * w;
      if (reverse) {
        svg.appendChild(make('rect', { x:x + w - bw, y:y, width:bw, height:h, rx:8, fill:fill }));
        text(svg, x + w - 8, y + 18, label, value < max * 0.45 ? 'value' : 'value-light', 'end');
      } else {
        svg.appendChild(make('rect', { x:x, y:y, width:bw, height:h, rx:8, fill:fill }));
        text(svg, x + 8, y + 18, label, value < max * 0.45 ? 'value' : 'value-light');
      }
      if (threshold !== null) {
        var tx = x + clamp(threshold / max, 0, 1) * w;
        svg.appendChild(make('line', { x1:tx, y1:y - 5, x2:tx, y2:y + h + 5, class:'threshold' }));
      }
    }
    function drawHeatCell(svg, x, y, w, h, fill, label, sublabel) {
      svg.appendChild(make('rect', { x:x, y:y, width:w, height:h, rx:10, fill:fill, stroke:'rgba(15,23,42,0.06)' }));
      text(svg, x + w/2, y + 24, label, fill === '#0284c7' ? 'value-light' : 'value', 'middle');
