      var cols = { country:34, score:248, supply:405, per:672, gw:940, precip:1190 };
      text(svg, cols.country, 27, 'Country', 'header-label');
      text(svg, cols.score, 27, 'Convergence score', 'header-label'); text(svg, cols.score, 45, 'relative severity, 0–100', 'unit-label');
      text(svg, cols.supply, 27, 'Supply ÷ demand', 'header-label'); text(svg, cols.supply, 45, 'ratio; <1 means demand exceeds supply', 'unit-label');
      text(svg, cols.per, 27, 'Freshwater per capita', 'header-label'); text(svg, cols.per, 45, 'm³/person/year, log scaled', 'unit-label');
      text(svg, cols.gw, 27, 'Groundwater extraction ÷ recharge', 'header-label'); text(svg, cols.gw, 45, 'ratio; >1 means overdraft', 'unit-label');
      text(svg, cols.precip, 27, 'Precipitation trend', 'header-label'); text(svg, cols.precip, 45, '1990s → 2010s, mm/year and Δ%', 'unit-label');
      svg.appendChild(make('line', {x1:24, y1:58, x2:1474, y2:58, class:'rule'}));
