        var y = top + i * rowH;
        svg.appendChild(make('rect', { x:14, y:y, width:1468, height:rowH-gap, rx:13, class:'row-bg ' + (d.score > 68 ? 'hot' : d.score < 25 ? 'low' : '') }));
        text(svg, cols.country, y + 23, (i + 1) + '.', 'country-rank');
        text(svg, cols.country + 28, y + 23, d.country, 'label');
        text(svg, cols.country + 30, y + 42, d.iso + ' · ' + d.stress, 'iso');
        drawBar(svg, cols.score, y + 13, 118, 24, d.score, 100, stressColor(d.score/100), Math.round(d.score).toString(), null, false);
        drawBar(svg, cols.supply, y + 13, 205, 24, d.supply, 6.2, stressColor(d.supplySeverity), formatNum(d.supply, 2) + '×', 1, true);
        text(svg, cols.supply, y + 48, d.supply < 1 ? 'demand exceeds renewable supply' : 'supply exceeds demand', 'small');
        var perLog = Math.log10(d.perCapita), perMin = Math.log10(80), perMax = Math.log10(100000);
