      text(svg, cols.supply + 33, 688, '1.0 threshold', 'unit-label');
      text(svg, cols.per + 55, 688, '1,000 m³ scarcity', 'unit-label');
      text(svg, cols.gw + 35, 688, '1.0 overdraft', 'unit-label');
    }
    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      ChartManager.safeInit('validationChart', { type:'bar', data:{ labels:countries.map(function(d){return d.iso;}), datasets:[{ label:'Convergence score', data:countries.map(function(d){return d.score;}), backgroundColor:'#be123c' }] }, options:{ responsive:true, maintainAspectRatio:false, plugins:{ tooltip:{ enabled:true }, legend:{ display:true } }, scales:{ y:{ beginAtZero:true } } } });
    }
    function onThemeChange() { renderMatrix(); buildCharts(); }
    window.addEventListener('load', function() { renderMatrix(); buildCharts(); });
  </script>
</body>
</html>
